    39→import { operationsService } from '../../services/operationsService';
    40→import type { ContractGeneration, OperationsSortOrder, OperationsFilterParams } from '../../types/legal';
    41→
    42→// Mapping of frontend sort field names to backend database fields
    43→const SORT_FIELD_MAP: Record<string, string> = {
    44→  'contract_id': 'contract_id',
    45→  'contract_type': 'contract_type',
    46→  'nombre_importador': 'data_snapshot->nombre_importador',
    47→  'client_nit': 'client_nit',
    48→  'cupo_plataforma': 'data_snapshot->cupo_plataforma',
    49→  'reviewed_at': 'reviewed_at',
    50→};
    51→
    52→const FKApprovedContracts: React.FC = () => {
    53→  const [contracts, setContracts] = useState<ContractGeneration[]>([]);
    54→  const [loading, setLoading] = useState(true);
    55→  const [error, setError] = useState<string | null>(null);
    56→  const [downloadingId, setDownloadingId] = useState<string | null>(null);
    57→  const [sortBy, setSortBy] = useState<string>('reviewed_at');
    58→  const [sortOrder, setSortOrder] = useState<OperationsSortOrder>('desc');
    59→
    60→  // Filter state
    61→  const [showFilters, setShowFilters] = useState(false);
    62→  const [filters, setFilters] = useState<OperationsFilterParams>({});
    63→  const [activeFilterCount, setActiveFilterCount] = useState(0);
    64→
    65→  // Count active filters
    66→  const countActiveFilters = useCallback((filterParams: OperationsFilterParams): number => {
    67→    let count = 0;
    68→    if (filterParams.contract_types && filterParams.contract_types.length > 0) count++;
    69→    if (filterParams.client_name && filterParams.client_name.trim()) count++;
    70→    if (filterParams.client_nit && filterParams.client_nit.trim()) count++;
    71→    if (filterParams.date_from) count++;
    72→    if (filterParams.date_to) count++;
    73→    if (filterParams.cupo_min !== undefined) count++;
    74→    if (filterParams.cupo_max !== undefined) count++;
    75→    return count;
    76→  }, []);
    77→
    78→  const loadApprovedContracts = useCallback(async () => {
    79→    try {
    80→      setLoading(true);
    81→      setError(null);
    82→      // Map frontend field name to backend field name
    83→      const backendSortField = SORT_FIELD_MAP[sortBy] || 'reviewed_at';
    84→      const data = await operationsService.getApprovedContracts(
    85→        filters,
    86→        backendSortField,
    87→        sortOrder
    88→      );
    89→      setContracts(data);
    90→    } catch (err) {
    91→      console.error('Error loading approved contracts:', err);
    92→      setError('Error al cargar los contratos aprobados');
    93→    } finally {
    94→      setLoading(false);
    95→    }
    96→  }, [filters, sortBy, sortOrder]);
    97→
    98→  useEffect(() => {
    99→    loadApprovedContracts();
   100→  }, [loadApprovedContracts]);
   101→
   102→  // Update active filter count when filters change
   103→  useEffect(() => {
   104→    setActiveFilterCount(countActiveFilters(filters));
   105→  }, [filters, countActiveFilters]);
   106→
   107→  const handleSortRequest = (column: string) => {
   108→    // If clicking the current sort column, toggle the order
   109→    if (sortBy === column) {
   110→      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
   111→    } else {
   112→      // If clicking a new column, set it as the sort column with descending order
   113→      setSortBy(column);
   114→      setSortOrder('desc');
   115→    }
   116→  };
   117→
   118→  // Filter handlers
   119→  const handleContractTypeChange = (type: string, checked: boolean) => {
   120→    setFilters((prev) => {
   121→      const currentTypes = prev.contract_types || [];
   122→      const newTypes = checked
   123→        ? [...currentTypes, type]
   124→        : currentTypes.filter((t) => t !== type);
   125→      return { ...prev, contract_types: newTypes.length > 0 ? newTypes : undefined };
   126→    });
   127→  };
   128→
   129→  const handleClearFilters = () => {
   130→    setFilters({});
   131→    setShowFilters(false);
   132→  };
   133→
   134→  const handleDownloadPDF = async (contract: ContractGeneration) => {
   135→    if (!contract.approved_document_url) {
   136→      alert('No hay PDF disponible para este contrato');
   137→      return;
   138→    }
   139→
   140→    try {
   141→      setDownloadingId(contract.id);
   142→
   143→      // Download via backend API endpoint
   144→      const blob = await operationsService.downloadApprovedContractPdf(contract.id);
   145→      const url = window.URL.createObjectURL(blob);
   146→      const link = document.createElement('a');
   147→      link.href = url;
   148→      link.download = `contrato_${contract.contract_id}_aprobado.pdf`;
   149→      document.body.appendChild(link);
   150→      link.click();
   151→      document.body.removeChild(link);
   152→      window.URL.revokeObjectURL(url);
   153→    } catch (err) {
   154→      console.error('Error downloading PDF:', err);
   155→      alert('Error al descargar el PDF');
   156→    } finally {
   157→      setDownloadingId(null);
   158→    }
   159→  };
   160→
   161→  const formatDate = (dateString: string) => {
   162→    return new Date(dateString).toLocaleString('es-CO', {
   163→      year: 'numeric',
   164→      month: 'long',
   165→      day: 'numeric',
   166→      hour: '2-digit',
   167→      minute: '2-digit',
   168→    });
   169→  };
   170→
   171→  const formatCurrency = (amount: number) => {
   172→    return new Intl.NumberFormat('es-CO', {
   173→      style: 'currency',
   174→      currency: 'COP',
   175→      minimumFractionDigits: 0,
   176→    }).format(amount);
   177→  };
   178→
   179→  const getContractTypeBadge = (contractType: string) => {
   180→    if (contractType === 'otrosi') {
   181→      return {
   182→        label: 'Otrosí No. 1',
   183→        color: 'warning' as const,
   184→      };
   185→    }
   186→    if (contractType === 'inventario_bodega') {
   187→      return {
   188→        label: 'Inventario Bodega 3ro',
   189→        color: 'success' as const,
   190→      };
   191→    }
   192→    return {
   193→      label: 'Activos',
   194→      color: 'info' as const,
   195→    };
   196→  };
   197→
   198→  if (loading) {
   199→    return (
   200→      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 300 }}>
   201→        <CircularProgress />
   202→      </Box>
   203→    );
   204→  }
   205→
   206→  if (error) {
   207→    return <Alert severity="error">{error}</Alert>;
   208→  }
   209→
   210→  if (contracts.length === 0 && activeFilterCount === 0) {
   211→    return (
   212→      <Alert severity="info" icon={<InfoIcon />}>
   213→        No hay contratos aprobados disponibles para descarga.
   214→      </Alert>
   215→    );
   216→  }
   217→
   218→  return (
   219→    <Box>
   220→      <Box sx={{ mb: 3, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
   221→        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
   222→          <Typography variant="h6" sx={{ fontWeight: 600 }}>
   223→            Contratos Aprobados ({contracts.length})
   224→          </Typography>
   225→          {activeFilterCount > 0 && (
   226→            <Chip
   227→              label={`${activeFilterCount} filtro${activeFilterCount > 1 ? 's' : ''} activo${activeFilterCount > 1 ? 's' : ''}`}
   228→              size="small"
   229→              color="primary"
   230→              onDelete={handleClearFilters}
   231→            />
   232→          )}
   233→        </Box>
   234→        <Box sx={{ display: 'flex', gap: 1 }}>
   235→          <Badge badgeContent={activeFilterCount} color="primary">
   236→            <Button
   237→              variant={showFilters ? 'contained' : 'outlined'}
   238→              size="small"
   239→              onClick={() => setShowFilters(!showFilters)}
   240→              startIcon={<FilterListIcon />}
   241→              sx={{ textTransform: 'none' }}
   242→            >
   243→              Filtros
   244→            </Button>
