   150→      link.click();
   151→      document.body.removeChild(link);
   152→      window.URL.revokeObjectURL(url);
   153→    } catch (err) {
   154→      console.error('Error downloading PDF:', err);
   155→      alert('Error al descargar el PDF');
   156→    } finally {
   157→      setDownloadingId(null);
   158→    }
   159→  };
   160→
   161→  const formatDate = (dateString: string) => {
   162→    return new Date(dateString).toLocaleString('es-CO', {
   163→      year: 'numeric',
   164→      month: 'long',
   165→      day: 'numeric',
   166→      hour: '2-digit',
   167→      minute: '2-digit',
   168→    });
   169→  };
   170→
   171→  const formatCurrency = (amount: number) => {
   172→    return new Intl.NumberFormat('es-CO', {
   173→      style: 'currency',
   174→      currency: 'COP',
   175→      minimumFractionDigits: 0,
   176→    }).format(amount);
